W=[
E('falcon','英 /ˈfɒlkən/，亦 /ˈfɔːlkən/；美 /ˈfælkən/','隼','一种善于飞行、捕猎的猛禽；常见的 peregrine falcon 就是游隼。','可靠链是后期拉丁 falco／falconem → 古法语 faucon → 英语 falcon。更早常被联系到 falx 镰刀，可能联想到弯钩或翼形，但也有日耳曼语来源说，不能把镰刀解释当成定论。',[['后期拉丁 falco／falconem','隼；更远来源有争议'],['古法语 faucon → 中古英语 faucon → falcon','鸟名进入英语，后来恢复 l 拼写']],'falcon 是隼这一类猛禽的名称，不是所有鹰类的统一名称。记忆时可以看它的尖长翅和捕猎形象；至于名字是否因镰刀状轮廓而来，仍应与可确认的词义分开。','a peregrine falcon；a falcon in flight；a falcon’s wings。','hawk、eagle、falcon 都是猛禽相关名称，但不是同一个分类。中文泛称“鹰”时，英文原词可能更具体。',('A falcon circled above the cliffs.','一只隼在悬崖上空盘旋。'),('The guide identified the bird as a peregrine falcon.','向导认出那只鸟是一只游隼。'),sources=['https://www.etymonline.com/word/falcon','https://en.wiktionary.org/wiki/falcon']),
E('falconer','英 /ˈfɒlkənə/；美 /ˈfælkənər/','驯鹰师；训养并放飞猛禽的人','手上戴着厚手套，猛禽停在上面；这个人负责训练、照料并与鸟配合。','经古法语 fauconier／fauconer，由 faucon 隼构成。现代可联系 falcon + -er，但历史上是整个职业名从法语传入。',[['古法语 faucon → fauconier','隼 → 训养或用隼狩猎的人'],['中古英语 fauconer → falconer','驯鹰师、训养猛禽者']],'传统上与放鹰狩猎有关，现代也常出现在文化展示和猛禽训练语境。虽然名称以 falcon 为基础，相关活动并不只使用隼，还可能涉及其他猛禽。','an experienced falconer；a falconer’s glove；training with a falconer。','birdwatcher 是观察野鸟的人，falconer 与受训猛禽有直接照料和训练关系。看见猛禽不等于在从事 falconry。',('The falconer waited for the bird to return to his glove.','驯鹰师等着鸟飞回他的手套上。'),('An experienced falconer explained how the birds are cared for.','一位经验丰富的驯鹰师介绍了如何照料这些鸟。'),sources=['https://www.etymonline.com/word/falconer','https://ich.unesco.org/en/RL/falconry-a-living-human-heritage-01708']),
E('falconry','英 /ˈfɔːlkənri/；美 /ˈfælkənri/','驯鹰术；放鹰狩猎的传统活动','人与受训猛禽长期配合：照料、训练、放飞，再让鸟回到人身边。','来自法语 fauconnerie，基于 faucon 隼。现代能看出 falcon 词族，但不必把它说成英语 falconer 删改后才产生的词。',[['法语 faucon → fauconnerie','隼 → 训养、使用猛禽的活动'],['英语 falconry','驯鹰与放鹰狩猎的技艺和传统']],'通常不可数，指一整套实践与文化。它原先与获取猎物密切相关，现代语境也涉及传统传承、训练展示和人与自然的联系。不是简单把任何养鸟爱好叫作 falconry。','the art of falconry；a falconry demonstration；the history of falconry。','falcon 是鸟，falconer 是人，falconry 是技艺或活动。这三个词最适合放在同一场景里记。',('The festival included a falconry demonstration.','节庆活动中有一场驯鹰展示。'),('The museum explains the role of falconry in local traditions.','博物馆介绍了驯鹰活动在当地传统中的地位。'),sources=['https://www.etymonline.com/word/falconry','https://ich.unesco.org/en/RL/falconry-a-living-human-heritage-01708']),
E('falchion','英 /ˈfɔːltʃən/；美 /ˈfɔːltʃən/','单刃阔刀；一种中世纪刀剑','想象一把刀身较宽、单侧开刃的兵器；词名最初让人联想到镰刀一类的刃形。','古法语 fauchon 来自通俗拉丁重建形式 *falcionem，关联拉丁 falx 镰刀的小称。经中古英语 fauchoun，后来部分恢复拉丁式拼写。',[['拉丁 falx → 重建形式 *falcionem','镰刀及其相关刃器名称'],['古法语 fauchon → 中古英语 fauchoun → falchion','单刃宽刃刀剑']],'偏历史、博物馆与奇幻阅读词。不同实物的刀身轮廓并不完全相同，不能只凭“镰刀”词源就认定它必须像农具那样大幅弯曲。这里保留它，是因为它能清楚展示 falc- 的刃器支线。','a medieval falchion；the blade of a falchion；draw a falchion。','sword 是较宽泛的剑类名称；falchion 指一种特定历史刀剑。不要把它当成所有弯刀的通用词。',('The museum displayed a falchion beside a suit of armour.','博物馆在一套盔甲旁展示了一把中世纪单刃阔刀。'),('In the novel, the guard carried a falchion at his side.','小说中的卫兵腰间带着一把单刃阔刀。'),sources=['https://www.etymonline.com/word/falchion','https://en.wiktionary.org/wiki/falchion'])
]
ROOT=dict(id='C0402',meaning='镰刀；弯曲的刃形；隼名的可能关联',core='FALC = SICKLE',image='一条向内弯的刀刃。falchion 保留刃器联系；隼名 falcon 与这种形状的联系只是常见解释之一。',intro='拉丁 falx、属格 falcis 是镰刀或弯刃工具。原词根表把 falcon 也列在这里，但它的更远来源有争议。本页把确定的刃器支线与常用鸟名词族分清楚，不用一幅形象联想替代证据。',forms='falx 的词干是 falc-。falchion 经法语发生拼写变化；falcon 经 faucon 进入英语后恢复 l。falconer 和 falconry 都有自己的法语借入形式。',branches=[['刃器名称','falchion'],['隼与人的活动，远源存在争论','falcon、falconer、falconry']],contrasts='falcon 是隼，falconer 是驯鹰师，falconry 是驯鹰活动。把它们与镰刀形状联系起来可以辅助记忆，但不要把有争议的起源写成确定事实。',practice='The falconer demonstrated falconry with a trained falcon.\n\n驯鹰师用一只训练过的隼展示了驯鹰技艺。',words=[x['word'] for x in W],exclude={w:'较冷门的形态学或财务术语，先略过' for w in ['falcate','falciform','defalcation']})
